window.RULES = {"ru": {"ck": [["q1", "Первый академический период (семестр) полностью завершён?"], ["q2", "Подаёшь документы в летние или зимние каникулы?"], ["q3", "Переводишься на педагогическую или медицинскую программу?"], ["q4", "Есть сертификат ЕНТ или КТ не ниже порогового балла?"], ["q5", "Переводишься в национальный вуз и сейчас учишься на гранте?"]], "rules": ["<b>Когда:</b> только после полного завершения первого академического периода по индивидуальному учебному плану.", "<b>Сроки:</b> перевод проходит в летние и зимние каникулы. Если каникулы в вузах не совпадают, порядок определяет сам вуз.", "<b>Педагогика и медицина:</b> сертификат ЕНТ или КТ не ниже порогового балла плюс специальный экзамен, в том числе при переводе из зарубежного вуза.", "<b>Творческие программы:</b> при переходе на другую группу программ нужен сертификат ЕНТ не ниже порогового балла.", "<b>Национальные вузы:</b> перевод из другого вуза — только на платной основе.", "<b>Платный перевод:</b> процедуру каждый вуз устанавливает сам и описывает в своей академической политике.", "<b>Из зарубежного вуза:</b> транскрипт и сертификат ЕНТ/КТ. Без сертификата могут перевести на один академический период, за который нужно сдать тест."], "steps": ["Выбери вуз и программу, узнай в приёмной комиссии, сколько кредитов тебе перезачтут.", "В каникулы подай заявление в вуз, куда переводишься, и приложи транскрипт.", "Вуз определяет академическую разницу — предметы, которые придётся досдать.", "Руководитель нового вуза издаёт приказ о переводе.", "В течение 3 рабочих дней новый вуз запрашивает твоё личное дело из прежнего.", "Прежний вуз отчисляет тебя в связи с переводом и пересылает личное дело."], "docs": ["Заявление на имя руководителя вуза, куда переводишься", "Транскрипт или академическая справка", "Удостоверение личности", "Сертификат ЕНТ/КТ — для педагогики, медицины, творческих программ и перевода из-за рубежа", "Нотариальный перевод документов на казахский или русский — если они на иностранном языке"]}, "kz": {"ck": [["q1", "Бірінші академиялық кезең (семестр) толық аяқталды ма?"], ["q2", "Құжаттарды жазғы немесе қысқы демалыста тапсырасың ба?"], ["q3", "Педагогикалық немесе медициналық бағдарламаға ауысасың ба?"], ["q4", "Шекті балдан төмен емес ҰБТ немесе КТ сертификаты бар ма?"], ["q5", "Ұлттық ЖОО-ға ауысасың және қазір грантпен оқисың ба?"]], "rules": ["<b>Қашан:</b> жеке оқу жоспары бойынша бірінші академиялық кезең толық аяқталғаннан кейін ғана.", "<b>Мерзімі:</b> ауысу жазғы және қысқы демалыс кезінде өтеді. ЖОО-лардың демалысы сәйкес келмесе, тәртібін ЖОО өзі белгілейді.", "<b>Педагогика мен медицина:</b> шекті балдан төмен емес ҰБТ немесе КТ сертификаты және арнайы емтихан, шетелдік ЖОО-дан ауысқанда да.", "<b>Шығармашылық бағдарламалар:</b> басқа бағдарламалар тобына ауысқанда шекті балдан төмен емес ҰБТ сертификаты қажет.", "<b>Ұлттық ЖОО-лар:</b> басқа ЖОО-дан ауысу тек ақылы негізде.", "<b>Ақылы ауысу:</b> тәртібін әр ЖОО өзі белгілейді және академиялық саясатында көрсетеді.", "<b>Шетелдік ЖОО-дан:</b> транскрипт және ҰБТ/КТ сертификаты. Сертификатсыз бір академиялық кезеңге ауыстыруы мүмкін, осы уақытта тест тапсыру керек."], "steps": ["ЖОО мен бағдарламаны таңда, қабылдау комиссиясынан қанша кредит қайта есептелетінін біл.", "Демалыс кезінде ауысатын ЖОО-ға өтініш бер және транскриптті қос.", "ЖОО академиялық айырманы анықтайды — қайта тапсыратын пәндер.", "Жаңа ЖОО басшысы ауысу туралы бұйрық шығарады.", "3 жұмыс күні ішінде жаңа ЖОО бұрынғы ЖОО-дан жеке ісіңді сұратады.", "Бұрынғы ЖОО сені ауысуға байланысты шығарып, жеке ісіңді жібереді."], "docs": ["Ауысатын ЖОО басшысының атына өтініш", "Транскрипт немесе академиялық анықтама", "Жеке куәлік", "ҰБТ/КТ сертификаты — педагогика, медицина, шығармашылық бағдарламалар және шетелден ауысу үшін", "Құжаттар шет тілінде болса — қазақ немесе орыс тіліне нотариат куәландырған аударма"]}};
window.DOCS = {"ru": {"admission": [["a1", "Заявление", "Через egov.kz или в приёмной комиссии вуза. Приём документов — до 25 августа 2026 года."], ["a2", "Аттестат или диплом с приложением", "Оригинал."], ["a3", "Удостоверение личности", "Копия; вузы обычно просят две."], ["a4", "Сертификат ЕНТ", "Результаты текущего года поступления."], ["a5", "Свидетельство о присуждении гранта", "Если выиграл грант."], ["a6", "Фото 3×4", "Чаще всего 6 штук, некоторые вузы просят 4."], ["a7", "Медицинская справка 075/у", "Вместе со снимком флюорографии."], ["a8", "Прививочная карта 063/у", "Копия."], ["a9", "Приписное свидетельство или военный билет", "Для юношей."], ["a10", "Документы о льготах и квотах", "Если поступаешь по квоте."]], "transfer": [["t1", "Заявление", "На имя руководителя вуза, куда переводишься. Подаётся в летние или зимние каникулы."], ["t2", "Транскрипт или академическая справка", "Список освоенных дисциплин и кредитов."], ["t3", "Удостоверение личности", "Копия."], ["t4", "Сертификат ЕНТ или КТ", "Для педагогики, медицины, творческих программ и перевода из-за рубежа — с баллом не ниже порогового."], ["t5", "Результат специального экзамена", "Для педагогических и медицинских программ."], ["t6", "Нотариальный перевод документов", "Если документы на иностранном языке — на казахский или русский."]], "note": "Точный список зависит от вуза — сверяйся с сайтом или приёмной комиссией."}, "kz": {"admission": [["a1", "Өтініш", "egov.kz арқылы немесе ЖОО қабылдау комиссиясында. Құжаттар 2026 жылғы 25 тамызға дейін қабылданады."], ["a2", "Қосымшасы бар аттестат немесе диплом", "Түпнұсқа."], ["a3", "Жеке куәлік", "Көшірме; әдетте екеуін сұрайды."], ["a4", "ҰБТ сертификаты", "Түсу жылының нәтижелері."], ["a5", "Грант беру туралы куәлік", "Грант ұтсаң."], ["a6", "3×4 фото", "Көбіне 6 дана, кейбір ЖОО 4 дана сұрайды."], ["a7", "075/у медициналық анықтама", "Флюорография суретімен бірге."], ["a8", "063/у екпе картасы", "Көшірме."], ["a9", "Тіркеу куәлігі немесе әскери билет", "Ер балаларға."], ["a10", "Жеңілдік пен квотаны растайтын құжаттар", "Квотамен түссең."]], "transfer": [["t1", "Өтініш", "Ауысатын ЖОО басшысының атына. Жазғы немесе қысқы демалыста беріледі."], ["t2", "Транскрипт немесе академиялық анықтама", "Игерілген пәндер мен кредиттер тізімі."], ["t3", "Жеке куәлік", "Көшірме."], ["t4", "ҰБТ немесе КТ сертификаты", "Педагогика, медицина, шығармашылық бағдарламалар және шетелден ауысу үшін — шекті балдан төмен емес."], ["t5", "Арнайы емтихан нәтижесі", "Педагогикалық және медициналық бағдарламаларға."], ["t6", "Құжаттардың нотариалды аудармасы", "Құжаттар шет тілінде болса — қазақ немесе орыс тіліне."]], "note": "Нақты тізім ЖОО-ға байланысты — сайтынан немесе қабылдау комиссиясынан тексер."}};
